def project_discovery_complete(public_token):
    project = _get_project_by_token(public_token)
    if not project:
        abort(404)
    if project.get("status") == "DRAFT":
        return redirect(url_for("project_discovery_step", public_token=public_token, step=2))
    # V78: an old completion URL must not tell a client that IBROWS is reviewing
    # a finished submission while the assessment is actually waiting on them.
    # Send them to the first real clarification step, or Step 6 when the status
    # was set manually and there is no generated clarification checklist.
    if project.get("status") == "NEEDS_CLARIFICATION":
        clarification_steps = _project_client_clarifications(project)
        target_step = min(clarification_steps.keys()) if clarification_steps else 6
        return redirect(url_for("project_discovery_step", public_token=public_token, step=target_step))
    message = f"Hello IBROWS Enterprise. I have submitted Project Discovery {project['reference']} and would like to discuss it."
    whatsapp_url = f"https://wa.me/265882242594?text={quote(message, safe='')}"
    return render_template_string(
        PROJECT_DISCOVERY_TEMPLATE,
        mode="complete", step=None, step_title="", heading="Your project is taking shape.",
        subheading="Your requirements are now with IBROWS for review.",
        project=project, whatsapp_url=whatsapp_url, error="",
        clarification_mode=(request.args.get("clarification") == "1"),
    ), 200

