def admin_project_quotation_issue(project_id):
    validate_csrf()
    if request.form.get("confirm_issue") != "1":
        abort(400)
    project = _get_project_by_id(project_id)
    if not project:
        abort(404)
    costing = _costing_view(_get_project_costing(project))
    if costing.get("status") != "APPROVED_FOR_QUOTE" or not costing.get("quote_reference"):
        return redirect(url_for("admin_project_costing", project_id=project_id))
    existing = _get_project_quotation_by_reference(project_id, costing["quote_reference"])
    if existing:
        return redirect(url_for("admin_project_quotation_detail", project_id=project_id, quotation_id=existing["id"]))
    try:
        valid_days = int(request.form.get("valid_days") or 14)
    except Exception:
        valid_days = 14
    valid_days = max(1, min(valid_days, 60))
    snapshot = _quotation_snapshot(project, costing)
    public_token = secrets.token_urlsafe(32)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(revision_no), 0) + 1 FROM project_quotations WHERE project_id=%s", (project_id,))
            revision_no = int((cur.fetchone() or [1])[0] or 1)
            cur.execute(
                """
                INSERT INTO project_quotations (
                    project_id, quote_reference, revision_no, public_token,
                    status, snapshot, issued_at, valid_until, updated_at
                ) VALUES (%s, %s, %s, %s, 'ISSUED', %s::jsonb, NOW(), NOW() + (%s * INTERVAL '1 day'), NOW())
                RETURNING id
                """,
                (project_id, costing["quote_reference"], revision_no, public_token, json.dumps(snapshot), valid_days),
            )
            quotation_id = cur.fetchone()[0]
            _quote_event_insert(cur, quotation_id, "ISSUED", f"Quotation issued by IBROWS with {valid_days}-day validity.")
            cur.execute("UPDATE project_assessments SET status='QUOTED', updated_at=NOW() WHERE id=%s", (project_id,))
            _project_activity_insert(cur, project_id, "QUOTE_ISSUED", f"Quotation {costing['quote_reference']} issued as revision {revision_no}.")
        conn.commit()
    return redirect(url_for("admin_project_quotation_detail", project_id=project_id, quotation_id=quotation_id))

admin_quotation_delivery_ui_js.code_excerpt:
def admin_quotation_delivery_ui_js():
    script = r"""
(function () {
  function fallbackCopy(text) {
    var area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();
    area.setSelectionRange(0, area.value.length);
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    document.body.removeChild(area);
    return ok;
  }

  function showCopied(button) {
    var original = button.getAttribute('data-original-label') || button.textContent;
    button.setAttribute('data-original-label', original);
    button.textContent = 'Copied ✓';
    setTimeout(function () { button.textContent = original; }, 2200);
  }

  var button = document.getElementById('copyWhatsappMessage');
  var source = document.getElementById('quoteWhatsappMessage');
  if (!button || !source) return;

  button.addEventListener('click', function () {
    var text = source.value || source.textContent || '';
    if (!text) return;
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(function () {
        showCopied(button);
      }).catch(function () {
        if (fallbackCopy(text)) showCopied(button);
      });
    } else if (fallbackCopy(text)) {
      showCopied(button);
    }
  });
})();
"""
    return Response(script, mimetype="application/javascript", headers={"Cache-Control": "no-store"})

