admin_construction_profile_upload.code_excerpt:
def admin_construction_profile_upload():
    validate_csrf()
    upload = request.files.get("profile_pdf")
    if not upload or not upload.filename:
        return redirect(url_for("admin_construction_portfolio", message="Choose a PDF company profile first.", message_type="err"))
    try:
        data = _construction_read_upload(upload, CONSTRUCTION_MAX_PROFILE_BYTES)
        if not data.lstrip().startswith(b"%PDF-"):
            raise ValueError("The selected company profile is not a valid PDF file.")
        filename = _construction_safe_filename(upload.filename, "BUA-Company-Profile.pdf")
        if not filename.lower().endswith(".pdf"):
            filename += ".pdf"
        digest = hashlib.sha256(data).hexdigest()
        with get_db() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    "UPDATE construction_portfolio_assets SET is_active=FALSE,updated_at=NOW() WHERE asset_type='PROFILE_PDF' AND is_active=TRUE"
                )
                cur.execute(
                    """
                    INSERT INTO construction_portfolio_assets
                        (asset_type,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES('PROFILE_PDF',%s,'application/pdf',%s,%s,%s,NULL,NULL,0,TRUE)
                    """,
                    (filename, data, len(data), digest),
                )
            conn.commit()
        print(f"CONSTRUCTION PROFILE PUBLISHED: filename={filename} bytes={len(data)}", flush=True)
        return redirect(url_for("admin_construction_portfolio", message="Company profile published successfully."))
    except ValueError as exc:
        return redirect(url_for("admin_construction_portfolio", message=str(exc), message_type="err"))

