admin_construction_images_upload.code_excerpt:
def admin_construction_images_upload():
    validate_csrf()
    uploads = [item for item in request.files.getlist("images") if item and item.filename]
    if not uploads:
        return redirect(url_for("admin_construction_portfolio", message="Choose at least one construction photo.", message_type="err"))
    if len(uploads) > CONSTRUCTION_MAX_IMAGES_PER_UPLOAD:
        return redirect(url_for("admin_construction_portfolio", message=f"Upload no more than {CONSTRUCTION_MAX_IMAGES_PER_UPLOAD} photos at a time.", message_type="err"))
    caption = " ".join(str(request.form.get("caption") or "").split()).strip()[:180]
    prepared = []
    batch_total = 0
    try:
        for upload in uploads:
            data = _construction_read_upload(upload, CONSTRUCTION_MAX_IMAGE_BYTES)
            batch_total += len(data)
            if batch_total > CONSTRUCTION_MAX_IMAGE_BATCH_BYTES:
                raise ValueError("Keep each construction photo upload batch at 12 MB or less.")
            mime_type, extension = _construction_detect_image_type(data)
            filename = _construction_safe_filename(upload.filename, f"construction{extension}")
            stem = os.path.splitext(filename)[0].strip(" .") or "construction"
            filename = f"{stem}{extension}"
            prepared.append((filename, mime_type, data, hashlib.sha256(data).hexdigest()))
    except ValueError as exc:
        return redirect(url_for("admin_construction_portfolio", message=str(exc), message_type="err"))

    inserted = 0
    duplicates = 0
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(display_order),0) FROM construction_portfolio_assets WHERE asset_type='IMAGE'")
            next_order = int(cur.fetchone()[0] or 0) + 10
            for filename, mime_type, data, digest in prepared:
                cur.execute(
                    """
                    INSERT INTO construction_portfolio_assets
                        (asset_type,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES('IMAGE',%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
                    ON CONFLICT DO NOTHING
                    RETURNING id
                    """,
                    (
                        filename, mime_type, data, len(data), digest,
                        caption or None,
                        caption or "BUA construction project work",
                        next_order,
                    ),
                )
                if cur.fetchone():
                    inserted += 1
                    next_order += 10
                else:
                    duplicates += 1
        conn.commit()
    message = f"Uploaded {inserted} construction photo{'s' if inserted != 1 else ''}."
    if duplicates:
        message += f" Skipped {duplicates} duplicate{'s' if duplicates != 1 else ''}."
    print(f"CONSTRUCTION PHOTOS UPLOADED: inserted={inserted} duplicates={duplicates}", flush=True)
    return redirect(url_for("admin_construction_portfolio", message=message))

