def admin_landscape_comparison_upload():
    validate_csrf()
    before = request.files.get("before_image")
    after = request.files.get("after_image")
    if not before or not before.filename or not after or not after.filename:
        return redirect(url_for("admin_service_portfolios", message="Choose both a before image and an after/concept image.", message_type="err"))
    try:
        b_name,b_mime,b_data,b_hash = _service_read_image_upload(before, SERVICE_PORTFOLIO_MAX_IMAGE_BYTES)
        a_name,a_mime,a_data,a_hash = _service_read_image_upload(after, SERVICE_PORTFOLIO_MAX_IMAGE_BYTES)
        if len(b_data) + len(a_data) > LANDSCAPING_COMPARISON_MAX_BATCH_BYTES:
            raise ValueError("Keep each landscaping before/after pair at 16 MB or less combined.")
    except ValueError as exc:
        return redirect(url_for("admin_service_portfolios", message=str(exc), message_type="err"))
    caption = _service_clean(request.form.get("caption"), 180)
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(display_order),0)+10 FROM landscaping_before_after_pairs")
            order = int(cur.fetchone()[0] or 10)
            cur.execute(
                """INSERT INTO landscaping_before_after_pairs
                   (before_filename,before_mime_type,before_bytes,before_size,before_sha256,after_filename,after_mime_type,after_bytes,after_size,after_sha256,caption,alt_text,display_order,is_active)
                   VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
                   ON CONFLICT(before_sha256,after_sha256) DO NOTHING RETURNING id""",
                (b_name,b_mime,b_data,len(b_data),b_hash,a_name,a_mime,a_data,len(a_data),a_hash,caption or None,caption or "Landscaping before and after",order),
            )
            row=cur.fetchone()
        conn.commit()
    msg = "Before / after pair uploaded." if row else "That before / after pair already exists."
    return redirect(url_for("admin_service_portfolios", message=msg))

