admin_design_media_upload.code_excerpt:
def admin_design_media_upload():
    validate_csrf()
    uploads = [item for item in request.files.getlist("media") if item and item.filename]
    if not uploads:
        return redirect(url_for("admin_service_portfolios", message="Choose at least one video or audio sample.", message_type="err"))
    if len(uploads) > SERVICE_PORTFOLIO_MAX_MEDIA_FILES_PER_UPLOAD:
        return redirect(url_for("admin_service_portfolios", message=f"Upload no more than {SERVICE_PORTFOLIO_MAX_MEDIA_FILES_PER_UPLOAD} video/audio samples at a time.", message_type="err"))
    caption = _service_clean(request.form.get("caption"), 180)
    prepared = []
    batch_total = 0
    try:
        for upload in uploads:
            # Read only up to the larger media ceiling first; kind-specific limits are
            # enforced immediately after signature detection.
            data = _construction_read_upload(upload, SERVICE_PORTFOLIO_MAX_VIDEO_BYTES)
            mime_type, extension, media_kind = _portfolio_sample_media_type(upload, data)
            if media_kind == "video" and len(data) > SERVICE_PORTFOLIO_MAX_VIDEO_BYTES:
                raise ValueError("Each video sample must be 30 MB or smaller.")
            if media_kind == "audio" and len(data) > SERVICE_PORTFOLIO_MAX_AUDIO_BYTES:
                raise ValueError("Each audio sample must be 15 MB or smaller.")
            batch_total += len(data)
            if batch_total > SERVICE_PORTFOLIO_MAX_MEDIA_BATCH_BYTES:
                raise ValueError("Keep each video/audio upload batch at 60 MB or less.")
            filename = _construction_safe_filename(upload.filename, f"creative-sample{extension}")
            prepared.append((filename, mime_type, data, hashlib.sha256(data).hexdigest(), media_kind))
    except ValueError as exc:
        return redirect(url_for("admin_service_portfolios", message=str(exc), message_type="err"))

    inserted = duplicates = 0
    with get_db() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT COALESCE(MAX(display_order),0) FROM website_service_portfolio_assets WHERE service_key='DESIGN_BRANDING'")
            next_order = int(cur.fetchone()[0] or 0) + 10
            for filename, mime_type, data, digest, media_kind in prepared:
                default_label = "Video marketing sample" if media_kind == "video" else "Jingle / audio sample"
                cur.execute(
                    """
                    INSERT INTO website_service_portfolio_assets
                        (service_key,filename,mime_type,file_bytes,byte_size,sha256,caption,alt_text,display_order,is_active)
                    VALUES('DESIGN_BRANDING',%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
                    ON CONFLICT (service_key,sha256) DO NOTHING RETURNING id
                    """,
                    (filename,mime_type,data,len(data),digest,caption or None,caption or default_label,next_order),
                )
                if cur.fetchone():
                    inserted += 1
                    next_order += 10
                else:
                    duplicates += 1
        conn.commit()
    message = f"Uploaded {inserted} creative media sample{'s' if inserted!=1 else ''}."
    if duplicates:
        message += f" Skipped {duplicates} duplicate{'s' if duplicates!=1 else ''}."
    return redirect(url_for("admin_service_portfolios", message=message))

