admin_service_request_tender_workflow.code_excerpt:
def admin_service_request_tender_workflow(request_id):
    validate_csrf()
    item = _get_website_service_request(request_id)
    if not item:
        abort(404)
    if item.get("service_key") != "CONSTRUCTION_TENDER":
        abort(404)
    allowed = {key for key, _label in TENDER_WORKFLOW_STEPS}
    selected = []
    seen = set()
    for raw in request.form.getlist("tender_step"):
        key = _service_clean(raw, 60)
        if key in allowed and key not in seen:
            selected.append(key)
            seen.add(key)
    tender_note = _service_clean_multiline(request.form.get("tender_note"), 3000)
    workflow = dict(item.get("admin_workflow") or {})
    workflow["tender_checklist"] = selected
    workflow["tender_note"] = tender_note
    workflow["tender_updated_label"] = datetime.now(ADMIN_TIMEZONE).strftime("%d %b %Y at %H:%M Malawi time")

    preset = _service_clean(request.form.get("deadline_reminder"), 20).upper() or "KEEP"
    reminder_at = None
    reminder_changed = False
    message = "Tender Control Desk saved."
    if preset != "KEEP":
        deadline = _service_tender_deadline_info(item.get("payload"))
        if not deadline or not deadline.get("utc"):
            message = "Tender Control Desk saved. No valid closing time is available for the reminder preset."
        elif deadline.get("is_closed"):
            message = "Tender Control Desk saved. The tender closing time has already passed, so no reminder was scheduled."
        else:
            now = datetime.now(UTC_TIMEZONE)
            if preset == "NOW":
                reminder_at = now + timedelta(minutes=5)
            else:
                hours = {"72H": 72, "24H": 24, "4H": 4}.get(preset)
                if hours is not None:
                    reminder_at = deadline["utc"] - timedelta(hours=hours)
                    if reminder_at <= now:
                        reminder_at = now + timedelta(minutes=5)
            if reminder_at is not None:
                reminder_changed = True
                message = f"Tender Control Desk saved. Follow-up scheduled for {reminder_at.astimezone(ADMIN_TIMEZONE).strftime('%d %b %Y at %H:%M Malawi time')}."

    with get_db() as conn:
        with conn.cursor() as cur:
            if reminder_changed:
                cur.execute(
                    """
                    UPDATE website_service_requests
                    SET admin_workflow=%s::jsonb,
                        follow_up_at=%s,follow_up_notified_at=NULL,
                        follow_up_notification_claimed_at=NULL,follow_up_notification_error=NULL,
                        updated_at=NOW()
                    WHERE id=%s
                    """,
                    (json.dumps(workflow), reminder_at, request_id),
                )
            else:
                cur.execute(
                    "UPDATE website_service_requests SET admin_workflow=%s::jsonb,updated_at=NOW() WHERE id=%s",
                    (json.dumps(workflow), request_id),
                )
        conn.commit()
    return redirect(url_for("admin_service_request_detail", request_id=request_id, message=message))

